  globalThis.__model = { parse: ai({ truong: [T("loai_bds", "nha_pho", "nhà phố")] }), create: () => "Dạ em ghi rồi anh. Giá anh mong muốn bao nhiêu ạ?" };
  rN = await send({ external_user_id: "rn-4", text: "nhà phố" });
