    globalThis.__model = { parse: ai({ vai: vaiAi, truong: [T("loai_giao_dich", "ban", "bán"), T("loai_bds", "dat", "đất")] }), create: () => "Dạ em ghi nhận rồi ạ. Lô đất mình rộng đường vào bao nhiêu ạ?" };
    await send({ external_user_id: uid, text: txt });
